// @FIGURE_CODE_BEGIN
// network volume → transparent BoxGeometry(4.8,7.0,3.2) very pale fill
// outer wireframe edges → CylinderGeometry black, thick, connecting the rectangular-prism corners
// internal layer planes → PlaneGeometry X-Z rectangles at y=1.6,3.2,4.8, translucent light gray
// internal plane outlines → CylinderGeometry medium gray, thinner, around each layer rectangle
// highlighted traversal slice → translucent PlaneGeometry plus golden cylinder outline at selected y
// dotted trajectories → LineDashedMaterial CatmullRomCurve3 paths through the stack
// lower data dots → SphereGeometry at path lower endpoints, black/gray
// path arrowheads → ConeGeometry at upper or lower curve endpoints, flipped by active direction
// side direction arrows → CylinderGeometry shafts plus ConeGeometry heads outside left/right of box
// labels → addLabel HTML serif text: Embedding, Data, Representation learning, Generative modeling

const boxW = 4.8;
const boxH = 7.0;
const boxD = 3.2;
const hx = boxW / 2;
const hz = boxD / 2;
const layerYs = [0, 1.6, 3.2, 4.8, 7.0];
const layerNames = ['Data', 'Layer 1', 'Layer 2', 'Layer 3', 'Embedding'];
const innerLayerYs = [1.6, 3.2, 4.8];

const blackMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
const greyEdgeMat = new THREE.MeshBasicMaterial({ color: 0x888888 });
const lightGreyEdgeMat = new THREE.MeshBasicMaterial({ color: 0xaaaaaa });
const activeGoldMat = new THREE.MeshBasicMaterial({ color: 0xf1b23a, transparent: true, opacity: 0.95 });
const inactiveSideMat = new THREE.MeshBasicMaterial({ color: 0x9a9a9a, transparent: true, opacity: 0.35 });
const activeSideMat = new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 1 });

function cylinderBetween(p1, p2, radius, material, segments = 14) {
  const start = p1.clone ? p1 : new THREE.Vector3(...p1);
  const end = p2.clone ? p2 : new THREE.Vector3(...p2);
  const mid = start.clone().add(end).multiplyScalar(0.5);
  const len = start.distanceTo(end);
  const geom = new THREE.CylinderGeometry(radius, radius, len, segments);
  const mesh = new THREE.Mesh(geom, material);
  mesh.position.copy(mid);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), end.clone().sub(start).normalize());
  mesh.renderOrder = 12;
  scene.add(mesh);
  return mesh;
}

function makeRectEdges(y, radius, material, parent = scene) {
  const pts = [
    new THREE.Vector3(-hx, y, -hz),
    new THREE.Vector3(hx, y, -hz),
    new THREE.Vector3(hx, y, hz),
    new THREE.Vector3(-hx, y, hz)
  ];
  const group = new THREE.Group();
  for (let i = 0; i < 4; i++) {
    const edge = cylinderBetween(pts[i], pts[(i + 1) % 4], radius, material);
    scene.remove(edge);
    group.add(edge);
  }
  parent.add(group);
  return group;
}

const volume = new THREE.Mesh(
  new THREE.BoxGeometry(boxW, boxH, boxD),
  new THREE.MeshBasicMaterial({
    color: 0xffffff,
    transparent: true,
    opacity: 0.025,
    depthWrite: false,
    side: THREE.DoubleSide
  })
);
volume.position.y = boxH / 2;
volume.renderOrder = 0;
scene.add(volume);

const outerCorners = [];
for (const x of [-hx, hx]) {
  for (const y of [0, boxH]) {
    for (const z of [-hz, hz]) {
      outerCorners.push(new THREE.Vector3(x, y, z));
    }
  }
}
makeRectEdges(0, 0.032, blackMat);
makeRectEdges(boxH, 0.032, blackMat);
for (const x of [-hx, hx]) {
  for (const z of [-hz, hz]) {
    cylinderBetween(new THREE.Vector3(x, 0, z), new THREE.Vector3(x, boxH, z), 0.028, blackMat);
