  plane.position.y = y;
  plane.renderOrder = 1 + i;
  plane.userData.layerName = layerNames[i + 1];
  scene.add(plane);
  registerInteractive(plane, {
    title: layerNames[i + 1],
    tooltip: `Current intermediate slice: ${layerNames[i + 1]}`,
    body: 'Each gray parallelogram is a horizontal layer of the same 3D rectangular network. A data point is gradually re-expressed as it crosses these slices.'
  });
  layerMeshes.push(plane);
  const outline = makeRectEdges(y, 0.016, greyEdgeMat);
  outline.renderOrder = 15;
});

const highlightPlane = new THREE.Mesh(
  new THREE.PlaneGeometry(boxW, boxD).rotateX(-Math.PI / 2),
  new THREE.MeshBasicMaterial({
    color: 0xffef9e,
    transparent: true,
    opacity: 0.32,
    side: THREE.DoubleSide,
    depthWrite: false
  })
);
highlightPlane.position.y = 0.01;
highlightPlane.renderOrder = 4;
scene.add(highlightPlane);

const highlightOutline = makeRectEdges(0.01, 0.026, activeGoldMat);
highlightOutline.renderOrder = 30;

const pathSpecs = [
