function buildCurve(spec, idx) {
  const s = new THREE.Vector3(...spec.start);
  const e = new THREE.Vector3(...spec.end);
  const pts = [
    s,
    new THREE.Vector3(
      THREE.MathUtils.lerp(s.x, e.x, 0.28) + spec.wiggle,
      1.6,
      THREE.MathUtils.lerp(s.z, e.z, 0.22) - 0.08
