    new THREE.Vector3(
      THREE.MathUtils.lerp(s.x, e.x, 0.52) - spec.wiggle * 0.45,
      3.2,
      THREE.MathUtils.lerp(s.z, e.z, 0.5) + 0.08
    ),
    new THREE.Vector3(
      THREE.MathUtils.lerp(s.x, e.x, 0.78) + spec.wiggle * 0.35,
      4.8,
      THREE.MathUtils.lerp(s.z, e.z, 0.8) - 0.04
    ),
    e
