function cylinderBetween(p1, p2, radius, material, segments = 14) {
  const start = p1.clone ? p1 : new THREE.Vector3(...p1);
  const end = p2.clone ? p2 : new THREE.Vector3(...p2);
  const mid = start.clone().add(end).multiplyScalar(0.5);
  const len = start.distanceTo(end);
  const geom = new THREE.CylinderGeometry(radius, radius, len, segments);
  const mesh = new THREE.Mesh(geom, material);
  mesh.position.copy(mid);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), end.clone().sub(start).normalize());
  mesh.renderOrder = 12;
  scene.add(mesh);
  return mesh;
}

function makeRectEdges(y, radius, material, parent = scene) {
  const pts = [
    new THREE.Vector3(-hx, y, -hz),
    new THREE.Vector3(hx, y, -hz),
    new THREE.Vector3(hx, y, hz),
    new THREE.Vector3(-hx, y, hz)
  ];
  const group = new THREE.Group();
  for (let i = 0; i < 4; i++) {
    const edge = cylinderBetween(pts[i], pts[(i + 1) % 4], radius, material);
    scene.remove(edge);
    group.add(edge);
  }
  parent.add(group);
  return group;
}

