      THREE.MathUtils.lerp(s.z, e.z, 0.5) + 0.08
    ),
    new THREE.Vector3(
      THREE.MathUtils.lerp(s.x, e.x, 0.78) + spec.wiggle * 0.35,
      4.8,
      THREE.MathUtils.lerp(s.z, e.z, 0.8) - 0.04
    ),
    e
  ];
  const curve = new THREE.CatmullRomCurve3(pts, false, 'catmullrom', 0.45);
  const sampled = curve.getPoints(120);
  const geom = new THREE.BufferGeometry().setFromPoints(sampled);
  const mat = new THREE.LineDashedMaterial({
    color: 0x666666,
    dashSize: 0.075,
    gapSize: 0.055,
    transparent: true,
    opacity: 0.95,
    depthWrite: false
  });
  const line = new THREE.Line(geom, mat);
  line.computeLineDistances();
  line.renderOrder = 25;
  scene.add(line);
  curveMaterials.push(mat);

  const dot = new THREE.Mesh(
    new THREE.SphereGeometry(0.09, 24, 16),
    new THREE.MeshBasicMaterial({ color: spec.dot })
  );
  dot.position.copy(s);
  dot.renderOrder = 35;
