    new THREE.ConeGeometry(0.105, coneHeight, 24),
    new THREE.MeshBasicMaterial({ color: 0x000000 })
  );
  cone.renderOrder = 36;
  scene.add(cone);

  const entry = { spec, curve, line, mat, dot, cone };
  registerInteractive(dot, {
    title: `Data point ${spec.name}`,
    tooltip: `Trace point ${spec.name}`,
    body: 'The filled dot is one input data location. Follow its dotted path upward to see representation learning, or downward to see generative modeling.'
