    new THREE.Vector3(hx, y, -hz),
    new THREE.Vector3(hx, y, hz),
    new THREE.Vector3(-hx, y, hz)
  ];
  for (let i = 0; i < 4; i++) {
    const edge = cylinderBetween(pts[i], pts[(i + 1) % 4], radius, material);
    scene.remove(edge);
    edge.renderOrder = renderOrder;
    group.add(edge);
  }
  parent.add(group);
  return group;
}

