function buildCurve(spec, idx) {
  const s = new THREE.Vector3(...spec.start);
  const p0 = new THREE.Vector3(...spec.pass0);
  const e = new THREE.Vector3(...spec.end);
  const pts = [
    s,
    p0,
    new THREE.Vector3(
      THREE.MathUtils.lerp(p0.x, e.x, 0.28) + spec.wiggle,
      1.6,
      THREE.MathUtils.lerp(p0.z, e.z, 0.25) - 0.08
    ),
    new THREE.Vector3(
      THREE.MathUtils.lerp(p0.x, e.x, 0.52) - spec.wiggle * 0.42,
      3.2,
      THREE.MathUtils.lerp(p0.z, e.z, 0.52) + 0.08
    ),
    new THREE.Vector3(
      THREE.MathUtils.lerp(p0.x, e.x, 0.78) + spec.wiggle * 0.34,
      4.8,
      THREE.MathUtils.lerp(p0.z, e.z, 0.80) - 0.04
    ),
    e
  ];
  const curve = new THREE.CatmullRomCurve3(pts, false, 'catmullrom', 0.42);
  const geom = new THREE.BufferGeometry().setFromPoints(curve.getPoints(150));
  const mat = new THREE.LineDashedMaterial({
    color: idx % 2 ? 0x666666 : 0x222222,
    dashSize: 0.070,
    gapSize: 0.055,
    transparent: true,
    opacity: 0.96,
    depthWrite: false
  });
  const line = new THREE.Line(geom, mat);
  line.computeLineDistances();
  line.renderOrder = 40;
  scene.add(line);
  curveMaterials.push(mat);

  const dot = new THREE.Mesh(
    new THREE.SphereGeometry(0.095, 28, 18),
    spec.dot === 0x666666 ? dataGrayMat : dataBlackMat
  );
  dot.position.copy(s);
  dot.renderOrder = 48;
  scene.add(dot);

  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(0.115, coneHeight, 28),
    new THREE.MeshBasicMaterial({ color: 0x000000 })
  );
  cone.renderOrder = 49;
  scene.add(cone);

  const entry = { spec, curve, line, mat, dot, cone };
  registerInteractive(dot, {
    title: `Data point ${spec.name}`,
    tooltip: `Input data point ${spec.name}`,
    body: 'The filled dot begins below the bottom face, then its dotted path passes through all layers toward an embedding.'
  });
  registerInteractive(line, {
    title: `Dotted trajectory ${spec.name}`,
    tooltip: 'Transformation through the stack',
    body: 'This dotted curve traces one data point as it changes representation from layer to layer.'
  });
  trajectories.push(entry);
}
