function makeDashedTubeCurve(curve, material, radius, renderOrder) {
  const group = new THREE.Group();
  const total = curve.getLength();
  const dashLen = 0.17;
  const gapLen = 0.13;
  const pieces = [];
  for (let dist = 0; dist < total - 0.02; dist += dashLen + gapLen) {
    const d0 = dist;
    const d1 = Math.min(dist + dashLen, total);
    const t0 = curve.getUtoTmapping(d0 / total);
    const t1 = curve.getUtoTmapping(d1 / total);
    const p0 = curve.getPoint(t0);
    const p1 = curve.getPoint(t1);
    const seg = makeCylinderBetween(p0, p1, radius, material, 10);
    seg.renderOrder = renderOrder;
    seg.material.depthTest = false;
    group.add(seg);
    pieces.push(seg);
  }
  scene.add(group);
  return { group, pieces };
}

function buildCurve(spec, idx) {
  const s = new THREE.Vector3(...spec.start);
  const e = new THREE.Vector3(...spec.end);
  const pts = [
    s,
    new THREE.Vector3(s.x + spec.wiggle * 0.30, 1.05, s.z + 0.08),
    new THREE.Vector3(
      THREE.MathUtils.lerp(s.x, e.x, 0.30) + spec.wiggle,
      1.6,
      THREE.MathUtils.lerp(s.z, e.z, 0.30) - 0.10
    ),
    new THREE.Vector3(
      THREE.MathUtils.lerp(s.x, e.x, 0.54) - spec.wiggle * 0.45,
      3.2,
      THREE.MathUtils.lerp(s.z, e.z, 0.54) + 0.10
    ),
    new THREE.Vector3(
      THREE.MathUtils.lerp(s.x, e.x, 0.78) + spec.wiggle * 0.35,
      4.8,
      THREE.MathUtils.lerp(s.z, e.z, 0.80) - 0.06
    ),
    e
  ];
  const curve = new THREE.CatmullRomCurve3(pts, false, 'catmullrom', 0.42);
  const lineGeom = new THREE.BufferGeometry().setFromPoints(curve.getPoints(180));
  const lineMat = new THREE.LineDashedMaterial({
    color: idx % 2 ? 0x555555 : 0x111111,
    dashSize: 0.095,
    gapSize: 0.070,
    linewidth: 3,
    transparent: true,
    opacity: 0.95,
    depthWrite: false,
    depthTest: false
  });
  const line = new THREE.Line(lineGeom, lineMat);
  line.computeLineDistances();
  line.renderOrder = 65;
  scene.add(line);
  curveMaterials.push(lineMat);

  const dashMat = new THREE.MeshBasicMaterial({
    color: idx % 2 ? 0x5c5c5c : 0x111111,
    transparent: true,
    opacity: 0.92,
    depthTest: false
  });
  const dash = makeDashedTubeCurve(curve, dashMat, 0.018, 64);
  dashGroups.push({ dash, mat: dashMat });

  const dot = new THREE.Mesh(
    new THREE.SphereGeometry(0.115, 30, 20),
    spec.dot === 0x666666 ? dataGrayMat : dataBlackMat
  );
  dot.position.copy(s);
  dot.renderOrder = 75;
  scene.add(dot);

  const cone = new THREE.Mesh(
    new THREE.ConeGeometry(0.135, coneHeight, 30),
    new THREE.MeshBasicMaterial({ color: 0x000000, depthTest: false })
  );
  cone.renderOrder = 78;
  scene.add(cone);

  const entry = { spec, curve, line, lineMat, dashMat, dot, cone };
  registerInteractive(dot, {
    title: `Data point ${spec.name}`,
    tooltip: `Input data point ${spec.name}`,
    body: 'The filled dot marks one input datum. Its dotted path shows that datum being transformed layer by layer.'
  });
  registerInteractive(line, {
    title: `Dotted trajectory ${spec.name}`,
    tooltip: 'Transformation through the stack',
    body: 'This dotted curve threads through every layer, linking a lower data location to an upper embedding location.'
  });
  trajectories.push(entry);
}
pathSpecs.forEach(buildCurve);

function pointOnCurveAtY(curve, y) {
  let prev = curve.getPoint(0);
  let best = prev.clone();
  let bestErr = Math.abs(prev.y - y);
  for (let i = 1; i <= 260; i++) {
    const t = i / 260;
    const p = curve.getPoint(t);
    if ((prev.y <= y && p.y >= y) || (prev.y >= y && p.y <= y)) {
      const a = (y - prev.y) / ((p.y - prev.y) || 1);
      return prev.clone().lerp(p, THREE.MathUtils.clamp(a, 0, 1));
    }
    const err = Math.abs(p.y - y);
    if (err < bestErr) {
      bestErr = err;
      best.copy(p);
    }
    prev = p;
  }
  return best;
}

const traversalMarkers = trajectories.map(() => {
  const marker = new THREE.Mesh(
    new THREE.SphereGeometry(0.090, 24, 16),
    new THREE.MeshBasicMaterial({ color: 0x111111, transparent: true, opacity: 0.92, depthTest: false })
  );
  marker.renderOrder = 82;
  scene.add(marker);
  return marker;
});

function setConeTipAndDirection(cone, tip, dir) {
  const n = dir.clone().normalize();
  cone.position.copy(tip).addScaledVector(n, -coneHeight / 2);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), n);
}

const leftArrow = new THREE.Group();
const rightArrow = new THREE.Group();
scene.add(leftArrow, rightArrow);

function addSideArrow(group, x, up) {
  const shaftStart = new THREE.Vector3(x, up ? -0.45 : 7.45, 0);
  const shaftEnd = new THREE.Vector3(x, up ? 7.45 : -0.45, 0);
  const shaft = makeCylinderBetween(shaftStart, shaftEnd, 0.055, sideBlackMat, 22);
  shaft.renderOrder = 80;
  group.add(shaft);

  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.285, 0.72, 34), sideBlackMat);
  const tip = new THREE.Vector3(x, up ? 7.90 : -0.90, 0);
  setConeTipAndDirection(cone, tip, new THREE.Vector3(0, up ? 1 : -1, 0));
  cone.renderOrder = 82;
  group.add(cone);
}
addSideArrow(leftArrow, -5.18, true);
addSideArrow(rightArrow, 5.18, false);

registerInteractive(leftArrow, {
  title: 'Representation learning',
  tooltip: 'Read upward: data → embedding',
  body: 'The upward arrow reads the stack as an encoder: data at the bottom is transformed into an embedding near the top.'
});
registerInteractive(rightArrow, {
  title: 'Generative modeling',
