bottomLabel.div.style.fontFamily = 'Georgia, Times New Roman, serif';

const leftLabel = addLabel('<span style="display:inline-block;transform:rotate(-90deg);">Representation learning</span>', new THREE.Vector3(-5.62, 3.50, 0), {
