const dirSelect = document.getElementById('activeDirection');
const layerSelect = document.getElementById('layerTraversal');
const stepTitle = document.getElementById('stepTitle');
const stepNarration = document.getElementById('stepNarration');

const demoSteps = [
  {
    title: 'Read upward: representation learning',
    narration: 'Start at the Data face. The dotted paths and arrowheads move upward through the same stack, showing data being transformed into an embedding.',
    state: { activeDirection: 'Representation learning', layerTraversal: 'Data' }
  },
  {
    title: 'Intermediate representation',
    narration: 'Advance to a middle plane. The selected slice highlights the current representation, and the points on that plane show the partially transformed data.',
    state: { activeDirection: 'Representation learning', layerTraversal: 'Layer 2' }
  },
  {
    title: 'Arrive at the embedding',
    narration: 'At the top plane, the trajectories have reached the embedding space. The left upward arrow is active, matching the bottom-to-top reading.',
    state: { activeDirection: 'Representation learning', layerTraversal: 'Embedding' }
  },
  {
    title: 'Read downward: generative modeling',
    narration: 'Switch direction. The same dotted paths now animate downward, showing a generative model reading the architecture from embedding back to data.',
    state: { activeDirection: 'Generative modeling', layerTraversal: 'Embedding' }
  },
  {
    title: 'Generate through layers',
    narration: 'Step downward through the intermediate planes. Each highlighted plane represents a stage in which an abstract embedding becomes more data-like.',
    state: { activeDirection: 'Generative modeling', layerTraversal: 'Layer 1' }
  }
];

let currentStep = 0;
let currentDirection = dirSelect.value;
let currentLayer = layerSelect.value;
let dashPhase = 0;

function setGroupMaterial(group, mat) {
  group.traverse(o => {
    if (o.isMesh) o.material = mat;
  });
}

function updatePathArrowheads() {
  const generative = currentDirection === 'Generative modeling';
  trajectories.forEach(tr => {
    if (generative) {
      const tip = tr.curve.getPoint(0);
      const near = tr.curve.getPoint(0.060);
      setConeTipAndDirection(tr.cone, tip, tip.clone().sub(near));
    } else {
      const tip = tr.curve.getPoint(1);
      const near = tr.curve.getPoint(0.940);
      setConeTipAndDirection(tr.cone, tip, tip.clone().sub(near));
    }
  });
}

function updateDirection() {
  const rep = currentDirection === 'Representation learning';
  setGroupMaterial(leftArrow, rep ? sideBlackMat : sideDimMat);
  setGroupMaterial(rightArrow, rep ? sideDimMat : sideBlackMat);
  leftLabel.div.style.color = rep ? '#000000' : '#9a9a9a';
  rightLabel.div.style.color = rep ? '#9a9a9a' : '#000000';

  trajectories.forEach((tr, i) => {
    const dark = rep ? (i % 2 ? 0x4a4a4a : 0x000000) : 0x555555;
    tr.lineMat.color.set(dark);
    tr.lineMat.opacity = rep ? 0.98 : 0.93;
    tr.dashMat.color.set(dark);
    tr.dashMat.opacity = rep ? 0.96 : 0.90;
  });
  updatePathArrowheads();
}

function updateHighlight() {
  const idx = Math.max(0, layerNames.indexOf(currentLayer));
  const y = layerYs[idx];

  selectedFill.position.y = y + 0.014;
  selectedOutline.position.y = y + 0.014;
  selectedFill.visible = true;
  selectedOutline.visible = true;

  layerMeshes.forEach(mesh => {
    const active = mesh.userData.layerName === currentLayer;
    mesh.material.color.set(active ? 0xf8f8f8 : 0xeeeeee);
    mesh.material.opacity = active ? 0.62 : 0.48;
  });

  layerOutlines.forEach((outline, i) => {
    const active = layerNames[i + 1] === currentLayer;
    outline.traverse(o => {
      if (o.isMesh) {
        o.material = active ? selectedEdgeMat : innerEdgeMat;
        o.scale.setScalar(active ? 1.035 : 1);
      }
    });
  });

  trajectories.forEach((tr, i) => {
    const markerPos = currentLayer === 'Embedding'
      ? tr.curve.getPoint(1)
      : currentLayer === 'Data'
        ? tr.curve.getPoint(0)
        : pointOnCurveAtY(tr.curve, y);
    traversalMarkers[i].position.copy(markerPos);
    traversalMarkers[i].scale.setScalar(currentLayer === 'Data' || currentLayer === 'Embedding' ? 1.18 : 1.0);
  });
}

function applyControls() {
  currentDirection = dirSelect.value;
  currentLayer = layerSelect.value;
  updateDirection();
  updateHighlight();
}

dirSelect.addEventListener('change', applyControls);
layerSelect.addEventListener('change', applyControls);

function goToStep(i) {
  currentStep = ((i % demoSteps.length) + demoSteps.length) % demoSteps.length;
  const step = demoSteps[currentStep];
  dirSelect.value = step.state.activeDirection;
  layerSelect.value = step.state.layerTraversal;
  stepTitle.textContent = step.title;
  stepNarration.textContent = step.narration;
  applyControls();
}
window.goToStep = goToStep;

document.getElementById('prevStep').addEventListener('click', () => goToStep(currentStep - 1));
document.getElementById('nextStep').addEventListener('click', () => goToStep(currentStep + 1));

applyControls();

(function animateFigureDetails() {
  requestAnimationFrame(animateFigureDetails);
  const sign = currentDirection === 'Representation learning' ? -1 : 1;
  dashPhase += sign * 0.010;
  curveMaterials.forEach((mat, i) => {
    mat.dashOffset = dashPhase + i * 0.035;
  });

  const t = performance.now() * 0.003;
  traversalMarkers.forEach((m, i) => {
    const base = currentLayer === 'Data' || currentLayer === 'Embedding' ? 1.18 : 1.0;
    m.scale.setScalar(base * (1 + 0.12 * Math.sin(t + i * 0.75)));
  });

  dashGroups.forEach((entry, i) => {
    const pulse = 0.86 + 0.10 * Math.sin(t * 1.2 + i * 0.65);
    entry.mat.opacity = (currentDirection === 'Representation learning' ? 0.96 : 0.90) * pulse;
  });
})();
